import{_ as e,o as i,c as l,ae as t}from"./chunks/framework.RRduUuAx.js";const _=JSON.parse('{"title":"定時記帳說明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh-HK/guide/12-scheduled-accounting-guide.md","filePath":"v1/zh-HK/guide/12-scheduled-accounting-guide.md"}'),r={name:"v1/zh-HK/guide/12-scheduled-accounting-guide.md"};function o(h,a,d,n,u,c){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="定時記帳說明" tabindex="-1">定時記帳說明 <a class="header-anchor" href="#定時記帳說明" aria-label="Permalink to &quot;定時記帳說明&quot;">​</a></h1><h2 id="_1-這是什麼功能" tabindex="-1">1. 這是什麼功能 <a class="header-anchor" href="#_1-這是什麼功能" aria-label="Permalink to &quot;1. 這是什麼功能&quot;">​</a></h2><p>「定時記帳」可以把一些固定、重複發生的收支（例如房租、水電、會員訂閱、薪資等）設定成規則，讓系統按規則自動生成帳單，減少重複手動輸入。</p><h2 id="_2-適用場景" tabindex="-1">2. 適用場景 <a class="header-anchor" href="#_2-適用場景" aria-label="Permalink to &quot;2. 適用場景&quot;">​</a></h2><ul><li>每月房租、房貸、信用卡還款</li><li>每週通勤交通費、固定餐補</li><li>每月訂閱服務（影片會員、雲端硬碟等）</li><li>每月固定收入（薪資、補貼等）</li></ul><h2 id="_3-如何使用" tabindex="-1">3. 如何使用 <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用&quot;">​</a></h2><ol><li>進入「設定」頁面，找到「定時記帳」</li><li>新增一條定時規則，填寫： <ul><li>收支類型：支出 / 收入</li><li>分類（收支項目）</li><li>金額</li><li>帳戶</li><li>標籤、備註（可選）</li><li>執行週期：每天 / 每週 / 每月（依規則選擇日期或星期）</li><li>起訖時間：開始時間必填；結束時間可選（到期後自動停止）</li></ul></li><li>儲存後，規則會出現在定時記帳列表中</li><li>到達觸發時間後，系統會按規則生成帳單</li></ol><h2 id="_4-使用規則與注意事項" tabindex="-1">4. 使用規則與注意事項 <a class="header-anchor" href="#_4-使用規則與注意事項" aria-label="Permalink to &quot;4. 使用規則與注意事項&quot;">​</a></h2><ul><li>定時記帳生成的帳單與一般手動帳單一致：會在列表顯示並參與統計匯總。</li><li>若你長時間不開啟 App，部分裝置可能無法做到「完全準點」生成；下次打開 App 時，系統會補齊到期但尚未生成的帳單（避免漏記）。</li><li>建議定期檢查規則列表，確認金額、分類、帳戶仍符合目前狀況（例如房租調整、換卡等）。</li><li>暫停/終止規則後將不再繼續生成帳單；恢復啟用後會從下一次週期繼續執行。</li></ul><h2 id="_5-常見問題" tabindex="-1">5. 常見問題 <a class="header-anchor" href="#_5-常見問題" aria-label="Permalink to &quot;5. 常見問題&quot;">​</a></h2><h3 id="q1-定時記帳生成錯了怎麼辦" tabindex="-1">Q1：定時記帳生成錯了怎麼辦？ <a class="header-anchor" href="#q1-定時記帳生成錯了怎麼辦" aria-label="Permalink to &quot;Q1：定時記帳生成錯了怎麼辦？&quot;">​</a></h3><p>定時記帳生成的帳單可以像一般帳單一樣編輯或刪除。若經常出錯，建議直接調整對應的定時規則（金額/週期/帳戶等）。</p><h3 id="q2-規則改了-之前生成的帳單會自動跟著改嗎" tabindex="-1">Q2：規則改了，之前生成的帳單會自動跟著改嗎？ <a class="header-anchor" href="#q2-規則改了-之前生成的帳單會自動跟著改嗎" aria-label="Permalink to &quot;Q2：規則改了，之前生成的帳單會自動跟著改嗎？&quot;">​</a></h3><p>不會。規則修改只影響後續生成的帳單；歷史帳單會保持不變，方便追溯。</p><h3 id="q3-同一天會生成多筆嗎" tabindex="-1">Q3：同一天會生成多筆嗎？ <a class="header-anchor" href="#q3-同一天會生成多筆嗎" aria-label="Permalink to &quot;Q3：同一天會生成多筆嗎？&quot;">​</a></h3><p>若你設定了多條規則，系統會分別生成對應的帳單。對同一條規則，系統會盡量避免重複生成。</p>',16)])])}const q=e(r,[["render",o]]);export{_ as __pageData,q as default};
